// Original scenario checks. New IDs preserve, rather than reinterpret, earlier answers.
const B=(en,zh)=>({en,zh});
const checks=new Map();
function C(module,prompt,options,hint,explanation,revision='v2'){
  const id='module.'+module;
  checks.set(id,{id:id+'.transfer-'+revision,type:'choice',prompt,options:options.map((text,i)=>({id:String.fromCharCode(97+i),text})),answer:'a',hints:[hint],explanation});
}

C('B01.01',B('A cultured cell takes in nutrients, releases waste and divides. Which observation most directly shows that it is an organized living system rather than an isolated molecule?','培养的细胞摄取营养、排出废物并分裂。哪项最直接说明它是有组织的生命系统，而不是孤立分子？'),[
 B('It coordinates multiple processes within a maintained cellular boundary.','它在维持细胞边界的同时协调多种过程。'),B('It contains carbon, which cannot occur outside living organisms.','它含有碳，而碳不可能存在于生物之外。'),B('It exchanges matter, which makes it exempt from conservation laws.','它交换物质，因此不受守恒定律约束。')],B('Ask what organization adds beyond the chemical identity of the parts.','思考组织结构在各组成部分的化学身份之外带来了什么。'),B('A cell combines a boundary, regulated reactions and inherited information into a functioning system. Carbon also occurs in nonliving matter; living systems still obey conservation laws while exchanging matter and energy.','细胞把边界、受调控的反应和遗传信息组织成能运作的系统。非生命物质也含碳；生命系统交换物质和能量，但仍遵守守恒定律。'));
C('B01.02',B('A membrane lets water pass but not a dissolved solute. The solution outside a cell has a higher concentration of that solute than the inside. Initially, which net water movement is expected if other effects are negligible?','某膜允许水通过，但不允许一种溶质通过。细胞外该溶质浓度高于细胞内。忽略其他作用，初始净水流向如何？'),[
 B('Out of the cell, toward the side with lower water potential.','流出细胞，朝水势较低的一侧移动。'),B('Into the cell, because every dissolved substance draws water inward.','流入细胞，因为一切溶解物都把水吸向细胞内。'),B('No movement, because the solute cannot cross the membrane.','没有移动，因为溶质无法穿过膜。')],B('Water and the dissolved solute have different permeability in this setup.','这个情境中水与溶质的通透性不同。'),B('With no compensating pressure difference, the higher nonpenetrating-solute concentration lowers external water potential. Water crosses outward by osmosis; the solute need not cross for this to occur.','没有补偿性压强差时，外侧较高的不可透过溶质浓度降低外侧水势。水通过渗透作用向外流动，并不要求溶质也穿膜。'));
C('B01.03',B('A eukaryotic cell makes a protein intended for secretion. Which route best fits the usual secretory pathway?','真核细胞合成一种待分泌蛋白。哪条路线最符合通常的分泌途径？'),[
 B('Rough endoplasmic reticulum → Golgi apparatus → secretory vesicle → cell surface.','粗面内质网 → 高尔基体 → 分泌囊泡 → 细胞表面。'),B('Nucleus → lysosome → mitochondrion → cell surface, with no ribosomes involved.','细胞核 → 溶酶体 → 线粒体 → 细胞表面，全程不需要核糖体。'),B('Cytosol → mitochondrial matrix → chromosome, where the protein becomes DNA.','细胞质基质 → 线粒体基质 → 染色体，蛋白质在那里变成 DNA。')],B('Follow the compartments that synthesize, modify and package secreted proteins.','追踪分泌蛋白合成、加工与包装的细胞区室。'),B('Secretory proteins are commonly synthesized into the rough ER by ribosomes, processed through the Golgi and carried in vesicles that fuse with the plasma membrane. The pathway does not convert protein into DNA.','分泌蛋白通常由核糖体合成并进入粗面内质网，经高尔基体加工，再由囊泡运送并与质膜融合。该途径不会把蛋白质转变成 DNA。'));
C('B01.04',B('An enzyme speeds a reversible reaction in a closed mixture. Temperature and starting amounts stay the same. What changes after adding the enzyme?','酶加快密闭混合物中的可逆反应，温度与初始物质的量相同。加入酶会改变什么？'),[
 B('The approach to equilibrium is faster; the equilibrium ratio is unchanged.','更快达到平衡，但平衡比例不变。'),B('The equilibrium ratio shifts permanently because activation energy is lower.','因为活化能降低，平衡比例永久改变。'),B('The reaction becomes energy-releasing even if its free-energy change was positive.','即使原自由能变化为正，反应也会变为释放能量。')],B('Separate the activation barrier from the free-energy difference between states.','区分活化能垒与状态之间的自由能差。'),B('An enzyme lowers the kinetic barrier for forward and reverse reactions. It changes reaction rates, not the thermodynamic equilibrium constant or the free-energy difference between the specified states.','酶降低正逆反应的动力学能垒，改变反应速率，但不改变热力学平衡常数，也不改变指定状态之间的自由能差。'));
C('B01.05',B('A diploid cell has six chromosomes before DNA replication. After replication but before sister chromatids separate, which count is correct using centromeres to count chromosomes?','二倍体细胞在 DNA 复制前有六条染色体。复制完成但姐妹染色单体尚未分离时，按着丝粒计数，哪项正确？'),[
 B('Six chromosomes and twelve sister chromatids.','六条染色体、十二条姐妹染色单体。'),B('Twelve chromosomes and six sister chromatids.','十二条染色体、六条姐妹染色单体。'),B('Three chromosomes because replication halves ploidy.','三条染色体，因为复制使倍性减半。')],B('Replication duplicates DNA; separation changes how chromatids are counted as chromosomes.','复制使 DNA 加倍；分离决定染色单体何时分别计为染色体。'),B('Each of the six chromosomes now contains two sister chromatids, joined at the centromere region. Replication doubles DNA amount without halving ploidy or immediately doubling the chromosome count.','六条染色体各含两条在着丝粒区域相连的姐妹染色单体。复制使 DNA 量加倍，但不会使倍性减半，也不会立即让染色体数加倍。'));
C('B01.06',B('Cells exposed to a signal show a fluorescent response. A matched group without the signal also fluoresces equally strongly. What is the most justified conclusion?','受信号刺激的细胞出现荧光响应，但匹配的无信号组也产生同样强的荧光。最合理的结论是什么？'),[
 B('This comparison does not demonstrate a signal-specific increase in fluorescence.','这项比较没有证明信号引起特异的荧光增强。'),B('The signal must activate the pathway because fluorescence was observed.','只要观察到荧光，就说明信号一定激活了通路。'),B('All cell signaling is disproved by this one experiment.','这一次实验否定了所有细胞信号传导。')],B('The control estimates what happens without the proposed cause.','对照估计没有待检验原因时会发生什么。'),B('The relevant evidence is the difference from a matched control, not fluorescence alone. Equal responses can reflect background, an insensitive assay or another cause; the experiment does not establish the proposed effect.','关键证据是相对匹配对照的差异，而不是单独出现荧光。相同响应可能来自背景、检测不敏感或其他原因；本实验并未建立所提出的效应。'));

C('B02.01',B('An Aa parent and an aa parent produce offspring under ordinary Mendelian segregation with equal viability. What fraction is expected to be heterozygous?','Aa 与 aa 亲本杂交，符合通常孟德尔分离且各种基因型存活率相同。预计杂合子占多少？'),[
 B('1/2.','1/2。'),B('1/4.','1/4。'),B('All offspring.','全部后代。')],B('The aa parent always contributes a; list the two gametes from Aa.','aa 亲本总贡献 a；列出 Aa 亲本的两类配子。'),B('The Aa parent contributes A or a with equal probability; the aa parent contributes a. Offspring are Aa or aa in equal expected proportions, so the heterozygote probability is 1/2.','Aa 亲本等概率贡献 A 或 a，aa 亲本贡献 a。后代为 Aa 或 aa，期望比例相等，因此杂合子概率为 1/2。'));
C('B02.02',B('For a fully penetrant autosomal recessive trait, two unaffected parents have an affected child. Assume no new mutation and correct parentage. Which parental genotypes are required?','某常染色体隐性性状完全外显，两个未表现性状的亲本生出表现性状的孩子。假设无新突变且亲子关系正确，亲本基因型应为何？'),[
 B('Both parents are heterozygous carriers.','两个亲本均为杂合携带者。'),B('Both parents are homozygous for the unaffected allele.','两个亲本均为未表现性状等位基因的纯合子。'),B('At least one parent must be affected.','至少一个亲本必须表现该性状。')],B('An affected recessive child must inherit one recessive allele from each parent.','隐性性状孩子必须从每个亲本各继承一个隐性等位基因。'),B('An aa child receives a from each parent. Since both parents are unaffected under complete penetrance, neither is aa; each must therefore be Aa. This inference depends on the stated inheritance assumptions.','aa 孩子从双方各获得 a。完全外显且双方都未表现性状，说明双方都不是 aa，因此只能是 Aa。该推断依赖题目给定的遗传假设。'));
C('B02.03',B('In a testcross, an AB/ab individual has recombination fraction 0.20 between the loci. Assuming reciprocal recombinant classes are equally frequent, what fraction of its gametes is Ab?','测交中 AB/ab 个体两位点间重组率为 0.20。假定两类互补重组配子频率相等，其 Ab 配子占多少？'),[
 B('0.10.','0.10。'),B('0.20.','0.20。'),B('0.40.','0.40。')],B('The total recombinant fraction is shared by Ab and aB.','重组总比例由 Ab 和 aB 两类分担。'),B('Parental gametes are AB and ab. Recombinants Ab and aB together total 0.20, so each contributes 0.10. A recombination fraction refers to all recombinant classes combined.','亲本型配子是 AB、ab；重组型 Ab 与 aB 合计 0.20，故各占 0.10。重组率指所有重组类型之和。'));
C('B02.04',B('A species normally has 2n=12. Which description distinguishes triploidy from trisomy of one chromosome?','某物种通常 2n=12。哪项区分了三倍体与某一条染色体的三体？'),[
 B('Triploidy has 18 chromosomes; the single-chromosome trisomy has 13.','三倍体有 18 条染色体，单条染色体三体有 13 条。'),B('Both have 13 chromosomes because both add one chromosome.','两者都是 13 条，因为都增加一条染色体。'),B('Triploidy has 13 chromosomes; trisomy has 18.','三倍体有 13 条，三体有 18 条。')],B('A chromosome set and an individual chromosome are different counting units.','一套染色体与一条染色体是不同的计数单位。'),B('Here one haploid set contains six chromosomes. Triploidy is three complete sets, 3n=18; trisomy is the diploid complement plus one particular chromosome, 2n+1=13.','此时一套单倍染色体有六条。三倍体为完整三套，即 3n=18；三体则是在二倍体基础上增加某一条，即 2n+1=13。'));
C('B02.05',B('In a population at Hardy–Weinberg equilibrium, a recessive genotype has frequency 0.09. What is the expected heterozygote frequency?','处于哈代—温伯格平衡的种群中，隐性纯合基因型频率为 0.09。预计杂合子频率是多少？'),[
 B('0.42.','0.42。'),B('0.09.','0.09。'),B('0.91.','0.91。')],B('The recessive genotype frequency is q², not q.','隐性纯合基因型频率是 q²，不是 q。'),B('q=√0.09=0.3 and p=0.7. The heterozygote frequency is 2pq=2×0.7×0.3=0.42. This calculation uses the equilibrium assumption.','q=√0.09=0.3，p=0.7，因此杂合子频率为 2pq=2×0.7×0.3=0.42。计算使用了平衡假设。'));
C('B02.06',B('An experiment predicts a 3:1 phenotype ratio but observes 31:9 among 40 offspring. What should be done before rejecting the genetic model?','遗传模型预测表型比例为 3:1，40 个后代观察到 31:9。拒绝模型之前应怎样处理？'),[
 B('Compare the deviation with the sampling variation expected under the model.','将偏差与模型所预期的抽样波动比较。'),B('Reject it immediately because the observed ratio is not exactly 3:1.','立即拒绝，因为观察比例并非严格的 3:1。'),B('Declare it proven because 31 and 9 are close to 30 and 10.','宣布模型已被证明，因为 31、9 接近 30、10。')],B('A predicted probability gives expected counts, not guaranteed exact counts.','预测概率给出期望计数，不保证每次计数完全一致。'),B('Random segregation produces sampling variation. A goodness-of-fit analysis can quantify whether the deviation is surprising under the model, but either a close fit or a discrepancy alone does not establish a unique mechanism.','随机分离会产生抽样波动。拟合优度分析可衡量偏差在模型下是否罕见，但拟合接近或存在偏差本身，都不能唯一确定机制。'));

C('B03.01',B('One DNA duplex contains two labeled old strands. After two rounds of semiconservative replication in unlabeled material, how many of the four duplexes contain an old labeled strand?','一个 DNA 双链分子的两条旧链均有标记。在无标记原料中进行两轮半保留复制后，四个双链分子中有几个仍含旧的标记链？'),[
 B('Two.','两个。'),B('One.','一个。'),B('All four.','四个全部。')],B('Track each original strand separately; new strands are unlabeled.','分别追踪每条原始链，新合成链没有标记。'),B('Each of the two original strands remains in one duplex. After the second round there are four duplexes but still only two original strands, located in two different duplexes.','两条原始链各保留在一个双链分子中。第二轮后共有四个双链分子，但原始链仍只有两条，分处两个分子。'));
C('B03.02',B('Two mature mRNAs from one gene contain different combinations of exons. Which mechanism can explain this without changing the gene DNA sequence?','同一基因产生的两种成熟 mRNA 含不同的外显子组合。哪种机制能在不改变基因 DNA 序列的情况下解释这一现象？'),[
 B('Alternative splicing of a precursor RNA.','前体 RNA 的可变剪接。'),B('Changing every ribosome into a different chromosome.','将每个核糖体改变成不同的染色体。'),B('Converting introns directly into amino acids without translation.','不经过翻译就把内含子直接变成氨基酸。')],B('RNA processing can select different exon combinations from the same precursor.','RNA 加工可以从同一前体中选取不同的外显子组合。'),B('Alternative splicing joins different exon combinations into mature transcripts. It can yield different RNA and protein isoforms while the underlying genomic sequence remains the same.','可变剪接把不同外显子组合连接成成熟转录本。基因组序列保持不变，也能产生不同 RNA 及蛋白质异构体。'));
C('B03.03',B('An mRNA has an uninterrupted open reading frame of 303 nucleotides from the start codon through one terminal stop codon. How many amino acids are encoded, before any protein processing?','某 mRNA 从起始密码子到唯一末端终止密码子的连续开放阅读框共 303 个核苷酸。在蛋白质加工前，编码多少个氨基酸？'),[
 B('100.','100。'),B('101.','101。'),B('303.','303。')],B('There are three nucleotides per codon, and a stop codon encodes no amino acid.','每个密码子含三个核苷酸，终止密码子不编码氨基酸。'),B('303/3=101 codons, including the terminal stop. The start codon encodes the initiating amino acid; subtract only the stop, giving 100 amino acids.','303/3=101 个密码子，其中一个是终止密码子。起始密码子编码起始氨基酸，只扣除终止密码子，得到 100 个氨基酸。'));
C('B03.04',B('RNA synthesis stays constant but its first-order degradation constant doubles. In the same linear steady-state model, what happens to RNA abundance?','RNA 合成速率不变，一阶降解常数加倍。在同一线性稳态模型中，RNA 含量如何变化？'),[
 B('It falls to half its previous steady-state value.','降为先前稳态值的一半。'),B('It doubles because degradation creates more RNA.','加倍，因为降解产生更多 RNA。'),B('It must stay unchanged because transcription is unchanged.','必定不变，因为转录未改变。')],B('At steady state, synthesis equals degradation constant times abundance.','稳态时，合成速率等于降解常数乘以含量。'),B('For synthesis rate s and decay constant k, abundance is s/k. Replacing k with 2k gives s/(2k), half the original. Regulation can act through RNA stability as well as synthesis.','合成速率为 s、降解常数为 k 时，含量为 s/k；改为 2k 后得到 s/(2k)，是原来一半。调控既可作用于合成，也可作用于 RNA 稳定性。'));
C('B03.05',B('A single nucleotide is inserted early in a protein-coding region, away from splice boundaries. Which consequence is expected in the simplest case?','蛋白质编码区前部插入一个核苷酸，位置远离剪接边界。在最简单情形中，预计产生什么后果？'),[
 B('The downstream reading frame shifts, often changing many later codons.','下游阅读框移位，常改变许多后续密码子。'),B('Exactly one amino acid is inserted and all later codons stay unchanged.','恰好插入一个氨基酸，所有后续密码子保持不变。'),B('Only DNA length changes; codon grouping cannot change.','只改变 DNA 长度，密码子分组不可能改变。')],B('Group the sequence into triplets before and after adding one nucleotide.','比较插入一个核苷酸前后的三联体分组。'),B('An insertion not divisible by three alters triplet grouping downstream. It may also introduce an early stop. Inserting three nucleotides is different: it can preserve the frame, though local amino-acid effects still depend on position.','插入数不是三的倍数时，下游三联体分组改变，还可能引入提前终止。插入三个核苷酸则可能保留阅读框，但局部氨基酸变化仍取决于位置。'));
C('B03.06',B('A PCR assay produces the expected-size band in both the sample and the no-template control. What is the main interpretation?','PCR 检测在样本与无模板对照中都出现预期大小的条带。主要应如何解释？'),[
 B('Contamination or another assay artifact must be investigated before claiming sample-specific detection.','应先调查污染或其他检测伪影，再声称样本特异检出。'),B('The result proves the target was present only in the sample.','结果证明靶标只存在于样本中。'),B('The no-template control confirms that the target requires no DNA template.','无模板对照证明靶标不需要 DNA 模板。')],B('The no-template control should test whether a signal appears without the sample template.','无模板对照用于检验没有样本模板时是否仍出现信号。'),B('A positive no-template control undermines specificity of this run, for example through carryover contamination. Band size alone does not establish target identity or validate the sample result.','无模板对照呈阳性会削弱本次检测的可信度，例如可能有扩增产物污染。仅凭条带大小不能确定靶标身份，也不能验证样本结果。'));

C('B04.01',B('After a new pesticide is used, insects carrying a pre-existing resistance allele leave more offspring. Why can the allele become more common?','使用新农药后，携带原先就存在的抗性等位基因的昆虫留下更多后代。该等位基因为什么可能变常见？'),[
 B('Heritable differences affect reproductive success under the changed conditions.','新条件下，可遗传差异影响了繁殖成功。'),B('Each insect deliberately rewrites its DNA to match what it needs.','每只昆虫都主动按需求改写自身 DNA。'),B('The pesticide must have created the same useful mutation in every survivor.','农药必定在每个幸存者中创造了相同的有利突变。')],B('Distinguish selection of existing variation from the origin of variation.','区分对已有变异的选择与变异的起源。'),B('Natural selection changes allele frequencies when heritable differences influence offspring contribution. The example already specifies pre-existing variation; it does not require purposeful change or identical induced mutations.','当可遗传差异影响后代贡献时，自然选择就能改变等位基因频率。题目已说明变异原先存在，不需要假设主动改变或相同诱发突变。'));
C('B04.02',B('A rooted tree is written ((A,B),C). Which relationship is implied by this branching pattern?','有根系统树写作 ((A,B),C)。该分支图样说明什么关系？'),[
 B('A and B share a more recent common ancestor with each other than with C.','A 与 B 彼此的最近共同祖先，比它们与 C 的共同祖先更近。'),B('A is necessarily the direct ancestor of B.','A 必然是 B 的直接祖先。'),B('C is less evolved than A and B because it branches earlier.','C 分支较早，所以比 A、B 进化程度低。')],B('Read shared branching points, not left-to-right order or a ladder of progress.','读取共同分支点，不要把左右顺序当成进步阶梯。'),B('The A–B split is nested inside the larger clade containing C. The tree states common ancestry, not that one living tip is another tip’s ancestor or that earlier branches are less evolved.','A—B 的分叉位于包含 C 的更大支系内部。树描述共同祖先关系，并不说明某个现生末端是另一末端的祖先，也不表示较早分支进化程度较低。'));
C('B04.03',B('In the logistic model dN/dt=rN(1−N/K) with r>0, what happens to growth as N approaches K from below?','逻辑斯谛模型 dN/dt=rN(1−N/K) 中 r>0。当 N 从下方接近 K 时，增长率如何变化？'),[
 B('The net growth rate approaches zero because the density-dependent factor approaches zero.','密度制约因子趋近零，因此净增长率趋近零。'),B('The net growth rate increases without bound because N is large.','N 较大，所以净增长率无限增加。'),B('Every individual instantly dies when N=K.','N=K 时所有个体立即死亡。')],B('Evaluate the factor 1−N/K near the carrying capacity.','检查接近环境容纳量时 1−N/K 的值。'),B('As N/K approaches one, the factor 1−N/K approaches zero. K is an equilibrium population size in this simplified model, not a lethal threshold or a universal fixed property of every real environment.','N/K 趋近一时，1−N/K 趋近零。K 是这个简化模型中的平衡种群大小，不是致死阈值，也不是所有真实环境中永远不变的性质。'));
C('B04.04',B('Why is energy usually available in smaller amounts at higher trophic levels?','为何较高营养级通常可获得的能量较少？'),[
 B('Organisms use energy in metabolism and dissipate heat, and not all biomass is eaten or assimilated.','生物代谢利用能量并散失热量，且并非所有生物量都被摄食、同化。'),B('Energy is destroyed completely whenever an organism respires.','每次呼吸都会使能量完全消失。'),B('Atoms disappear at each feeding step, so matter cannot cycle.','每次取食都会使原子消失，因此物质不能循环。')],B('Conservation of energy does not imply complete transfer into the next consumer’s biomass.','能量守恒并不意味着全部能量都转入下一级消费者的生物量。'),B('Energy is conserved but becomes dispersed, especially as heat. Only a portion is stored in biomass available to the next level; matter can recycle while energy flows through the ecosystem.','能量守恒，但会分散，尤其转化为热。只有一部分储存在下一级可利用的生物量中；物质可以循环，能量则流经生态系统。'));
C('B04.05',B('Two foraging patches yield the same food energy, but one takes twice as long to reach and use. Under a model maximizing net energy gain per unit time, what must be compared?','两个觅食斑块提供相同食物能量，但其中一个往返和取食所需时间是另一个的两倍。若模型最大化单位时间净能量收益，应比较什么？'),[
 B('Net gain after costs divided by total time for each patch.','每个斑块扣除成本后的净收益除以总时间。'),B('Food energy alone, because time cannot affect a rate.','只比较食物能量，因为时间不影响速率。'),B('Distance alone, assuming energy costs and feeding time are always zero.','只比较距离，并假定能量成本与取食时间总为零。')],B('A rate has both a numerator and a time denominator.','速率同时包含分子与时间分母。'),B('The model evaluates (energy obtained−energy spent)/time. Equal gross energy does not guarantee equal gain rate. Predation risk, nutrition and other constraints may require a richer model.','该模型比较（获得能量−消耗能量）/时间。总能量相同不代表收益率相同；捕食风险、营养等约束还可能要求更完整的模型。'));
C('B04.06',B('Two habitats contain the same number of species. In one, individuals are spread fairly evenly; in the other, one species dominates almost all counts. Which statement is justified?','两个栖息地物种数相同。一个的个体数在物种间较均匀，另一个几乎全由单一物种占据。哪项合理？'),[
 B('Species richness is equal, but evenness differs.','物种丰富度相同，但均匀度不同。'),B('Every diversity measure must be identical.','所有多样性指标必定相同。'),B('The dominated habitat must have zero species richness.','被单一物种主导的栖息地丰富度必为零。')],B('Richness counts species; evenness describes their relative abundances.','丰富度计数物种，均匀度描述相对丰度分布。'),B('Equal richness does not imply equal community structure. Indices that incorporate relative abundance can differ strongly between these habitats, even when the species count is identical.','丰富度相同不意味着群落结构相同。即便物种计数相同，纳入相对丰度的指标也可能有明显差异。'));

C('B05.01',B('In a plant life cycle, a haploid gametophyte produces haploid gametes. Which division normally produces those gametes?','植物生活史中，单倍体配子体产生单倍体配子。通常通过哪种分裂产生？'),[
 B('Mitosis, retaining the haploid chromosome set.','有丝分裂，保持单倍染色体组。'),B('Meiosis, halving the chromosome set again.','减数分裂，再次将染色体组减半。'),B('Fertilization, because it always reduces ploidy.','受精，因为受精总使倍性降低。')],B('Track ploidy through sporophyte, spore, gametophyte and gamete.','追踪孢子体、孢子、配子体与配子的倍性。'),B('The diploid sporophyte produces haploid spores by meiosis. Spores grow into haploid gametophytes, which form gametes by mitosis; fertilization then restores diploidy.','二倍体孢子体通过减数分裂产生单倍体孢子。孢子发育为单倍体配子体，配子体通过有丝分裂形成配子，随后受精恢复二倍体。'));
C('B05.02',B('A young shoot lengthens at its tip, while an older woody stem increases in diameter. Which tissues best explain these two growth patterns?','幼嫩枝条在顶端伸长，而较老的木质茎直径增加。哪组组织最能解释这两种生长？'),[
 B('Apical meristems for lengthening; lateral meristems for secondary thickening.','顶端分生组织使其伸长，侧生分生组织使其次生加粗。'),B('Dead xylem vessels divide for both kinds of growth.','死亡的木质部导管分裂完成两种生长。'),B('Mature leaves alone generate all new stem tissues.','成熟叶片单独产生全部新茎组织。')],B('Meristems retain actively dividing cells at characteristic locations.','分生组织在特定位置保留活跃分裂细胞。'),B('Apical meristems drive primary growth that extends roots and shoots. Vascular and cork cambia are lateral meristems involved in secondary thickening in plants that show this growth.','顶端分生组织驱动初生生长，使根和枝条伸长。维管形成层、木栓形成层等侧生分生组织参与具有此类生长植物的次生加粗。'));
C('B05.03',B('Water potential is −0.2 MPa in soil and −0.6 MPa in a root cell. If the membrane permits water movement and these values stay fixed, which net movement is favored?','土壤水势为 −0.2 MPa，根细胞水势为 −0.6 MPa。膜允许水移动且这些值暂时固定时，净水流倾向何方？'),[
 B('From soil into the root cell, toward lower water potential.','从土壤进入根细胞，流向较低水势。'),B('From the root cell to soil, because −0.6 is numerically higher.','从根细胞到土壤，因为 −0.6 数值更大。'),B('No movement because both values are negative.','两者都为负，因此没有移动。')],B('Compare signed values: −0.2 is higher than −0.6.','比较带符号数值：−0.2 高于 −0.6。'),B('Water tends to move from higher to lower water potential, here from −0.2 to −0.6 MPa. The negative signs do not prevent flow; the potential difference determines its favored direction.','水倾向从较高水势流向较低水势，即从 −0.2 流向 −0.6 MPa。负号不会阻止流动，水势差决定倾向方向。'));
C('B05.04',B('A plant grows in a closed chamber supplied with labeled carbon dioxide and unlabeled water. Where should the labeled carbon appear during photosynthesis?','植物在密闭装置中获得带标记的二氧化碳与无标记水。光合作用中，标记碳应出现在哪里？'),[
 B('In newly synthesized organic carbon compounds.','新合成的有机含碳化合物中。'),B('Only in released oxygen gas, which contains carbon atoms.','只在释放的氧气中，因为氧气含碳原子。'),B('Nowhere, because plant dry matter comes entirely from soil minerals.','任何地方都不会，因为植物干物质全部来自土壤矿物。')],B('Carbon fixation incorporates carbon dioxide into organic molecules.','碳固定将二氧化碳的碳并入有机分子。'),B('Photosynthetic carbon fixation incorporates the labeled carbon into organic products. Oxygen gas contains no carbon atoms, and soil minerals are not the main source of a plant’s fixed carbon.','光合碳固定把标记碳并入有机产物。氧气不含碳原子，土壤矿物也不是植物固定碳的主要来源。'));
C('B05.05',B('A shoot bends toward a light source because cells on its shaded side elongate more. Which interpretation best connects mechanism to shape?','枝条因背光侧细胞伸长更多而弯向光源。哪项最好地把机制与形状联系起来？'),[
 B('Unequal growth across the shoot causes curvature; the response depends on tissue and signaling context.','枝条两侧生长不均造成弯曲，响应取决于组织与信号情境。'),B('All cells migrate toward the light while retaining the same shape.','所有细胞保持相同形状并迁移到光源方向。'),B('Every plant organ must respond identically to every hormone concentration.','所有植物器官对所有激素浓度都必定有相同响应。')],B('Compare elongation on the two sides rather than imagining whole-cell migration.','比较两侧伸长，不要想象整细胞迁移。'),B('A longer shaded side bends the shoot toward the shorter illuminated side. Hormonal responses depend on concentration, cell type and context; a shoot result cannot automatically be transferred to a root.','背光侧伸长较多，使枝条弯向较短的受光侧。激素响应取决于浓度、细胞类型与情境，不能把枝条结果自动套用于根。'));
C('B05.06',B('To test whether fertilizer changes plant biomass, one pot receives fertilizer and another does not. Ten leaves are measured from each pot. What is the main replication limitation?','检验肥料是否改变植物生物量：一个盆施肥，一个盆不施肥，每盆测十片叶。主要的重复设置局限是什么？'),[
 B('There is only one independently treated pot per condition; leaves are subsamples.','每种条件只有一个独立处理的盆，叶片只是子样本。'),B('There are ten independent treatment replicates per condition because ten leaves were measured.','每种条件有十个独立处理重复，因为测了十片叶。'),B('Measuring more leaves automatically removes every difference between the two pots.','增加测量叶片数会自动消除两盆的所有差异。')],B('Identify the unit to which treatment was independently assigned.','找出处理被独立分配到的单位。'),B('Fertilizer was assigned at the pot level. Leaves within a pot share treatment and environment, so they cannot replace multiple independently treated pots. More pots are needed to separate treatment from pot-specific effects.','肥料按盆分配。同盆叶片共享处理和环境，不能替代多个独立处理的盆；需要更多盆才能区分处理效应与单盆特殊效应。'));

C('B06.01',B('Two animals both have wings but acquired them in separate evolutionary lineages. What does wing similarity alone establish?','两种动物都有翅膀，但翅膀在不同演化支系中分别形成。仅凭翅膀相似能说明什么？'),[
 B('Similar function may reflect convergence; additional evidence is needed to infer close ancestry.','相似功能可能反映趋同，推断近缘关系还需要其他证据。'),B('They must be each other’s closest living relatives.','它们必定互为最近的现生近亲。'),B('All anatomical traits are useless for reconstructing ancestry.','所有解剖性状都无法用于重建祖先关系。')],B('Separate functional resemblance from homology of the feature being compared.','区分功能相似与所比较结构的同源性。'),B('Similar selective pressures can produce analogous adaptations independently. Anatomy remains useful, but ancestry is inferred from multiple characters and other evidence, with careful identification of homology.','相似选择压力可独立产生相似适应。解剖学仍有价值，但祖先关系应结合多个性状和其他证据，并谨慎判断同源性。'));
C('B06.02',B('Body temperature rises above a regulated range and activates heat-loss responses that reduce the rise. What kind of feedback is this?','体温升高超过调节范围，激活散热反应，从而抑制这次升高。这属于哪种反馈？'),[
 B('Negative feedback because the response opposes the initial deviation.','负反馈，因为响应抵消了初始偏离。'),B('Positive feedback because the response is beneficial.','正反馈，因为响应有益。'),B('No feedback because the regulated value is not perfectly constant.','没有反馈，因为调节值并非绝对不变。')],B('Feedback sign describes direction relative to the deviation, not whether the result is good.','反馈正负描述与偏离方向的关系，不描述结果好坏。'),B('Negative feedback counteracts a change in the regulated variable. It can stabilize a range without maintaining an absolutely constant number; beneficial effects do not define positive feedback.','负反馈抵消被调节变量的变化，可以稳定一个范围而不维持绝对恒值。“有益”并不是正反馈的定义。'));
C('B06.03',B('A respiratory surface becomes thicker while area and concentration difference remain the same. Under a diffusion model, what happens to transfer rate?','呼吸表面变厚，但面积与浓度差不变。根据扩散模型，物质转移速率如何变化？'),[
 B('It decreases because the diffusion path is longer.','下降，因为扩散路径更长。'),B('It increases because a thicker barrier always increases diffusion.','上升，因为屏障越厚扩散总是越快。'),B('It cannot change because only total body mass controls diffusion.','不可能改变，因为只有体重控制扩散。')],B('For the same area and concentration difference, flux is inversely related to path length.','面积与浓度差相同时，通量与路径长度成反比。'),B('Fick-type diffusion gives transfer proportional to area times concentration difference divided by thickness, with other properties fixed. A thicker exchange barrier therefore slows transfer.','其他性质固定时，菲克型扩散的转移量与面积、浓度差成正比，与厚度成反比，因此较厚交换屏障会降低转移速率。'));
C('B06.04',B('A model kidney filters 100 units of a solute, reabsorbs 80 and secretes another 10 into the tubule. How much is excreted?','模型肾脏滤过某溶质 100 单位，重吸收 80 单位，又向小管分泌 10 单位。最终排出多少？'),[
 B('30 units.','30 单位。'),B('10 units.','10 单位。'),B('190 units.','190 单位。')],B('Track which transfers add solute to, or remove it from, the future urine.','追踪哪些过程向未来尿液添加溶质，哪些过程移走溶质。'),B('Excretion=filtration−reabsorption+secretion=100−80+10=30. Reabsorption returns material from the tubule to the body; secretion adds material to the tubule.','排出量=滤过−重吸收+分泌=100−80+10=30。重吸收从小管把物质送回体内，分泌则向小管添加物质。'));
C('B06.05',B('A hormone circulates throughout the body, but only certain cells respond. Which explanation is most direct?','某激素在全身循环，但只有部分细胞响应。最直接的解释是什么？'),[
 B('Responsive cells have appropriate receptors and downstream signaling machinery.','响应细胞具有适当受体与下游信号机制。'),B('Every cell must respond equally because the blood carries the hormone everywhere.','血液把激素带到各处，所以所有细胞必须同样响应。'),B('Hormones act only by becoming permanent parts of every cell’s DNA.','激素只能通过永久成为每个细胞 DNA 的一部分起作用。')],B('Signal delivery and signal recognition are distinct steps.','信号到达与信号识别是不同步骤。'),B('A target cell needs the receptor and cellular context to convert hormone binding into a response. Circulation distributes the signal but does not make all cells equally competent to detect or interpret it.','靶细胞需要受体与相应细胞条件，才能把激素结合转为响应。循环分配信号，但不会使所有细胞都同样能够识别、处理它。'));
C('B06.06',B('In a typical diploid animal life cycle, meiosis produces haploid gametes and fertilization fuses them. Why does alternating these processes stabilize chromosome-set number across sexual generations?','在典型二倍体动物生活史中，减数分裂产生单倍体配子，受精使配子融合。两过程交替为何能稳定有性世代之间的染色体组数？'),[
 B('Meiosis halves the set number and fertilization restores it.','减数分裂使组数减半，受精将其恢复。'),B('Both processes independently double the set number.','两过程都分别使组数加倍。'),B('Fertilization removes every chromosome inherited from one parent.','受精会移除来自某一亲本的全部染色体。')],B('Track diploid parent → haploid gametes → diploid zygote.','追踪二倍体亲本 → 单倍体配子 → 二倍体合子。'),B('In this animal cycle, meiosis changes 2n to n and fusion combines n+n into 2n. This prevents chromosome sets from doubling each generation while combining parental inheritance. In plants, meiosis instead forms spores, and the haploid gametophyte produces gametes by mitosis.','在这个动物生活史中，减数分裂使 2n 变为 n，融合使 n+n 恢复 2n，既结合双方遗传信息，又避免组数每代加倍。植物则通过减数分裂产生孢子，再由单倍体配子体通过有丝分裂产生配子。'),'v3');

C('B07.01',B('A microbial culture initially grows exponentially but later levels off in a closed vessel. Which explanation is compatible with this change?','微生物培养物最初指数增长，但后来在封闭容器中趋于平台。哪项解释与此变化相容？'),[
 B('Resources become limiting or waste accumulates, changing net population growth.','资源受限或废物积累，使种群净增长发生变化。'),B('Each cell loses its DNA as soon as the curve becomes horizontal.','曲线变水平时，每个细胞都失去 DNA。'),B('Exponential growth must continue forever regardless of the environment.','无论环境如何，指数增长都必须永远持续。')],B('Exponential growth assumes conditions that need not persist in a closed culture.','指数增长依赖的条件，在封闭培养中未必持续成立。'),B('Nutrients, space, oxygen or inhibitory products can change division and death rates. A plateau is a population-level balance and does not necessarily mean every cell has stopped all activity.','营养、空间、氧气或抑制产物可改变分裂率与死亡率。平台是种群水平的平衡，不一定表示每个细胞都停止一切活动。'));
C('B07.02',B('A virus enters a permissive host cell and produces new particles using host machinery. Why is an isolated virus particle not a self-sufficient reproducing cell?','病毒进入允许其复制的宿主细胞，利用宿主机制产生新颗粒。为什么孤立病毒颗粒不是能自给自足繁殖的细胞？'),[
 B('It depends on cellular machinery and resources for production of new particles.','它依赖细胞机制与资源来产生新颗粒。'),B('It must contain no genetic information of any kind.','它必定不含任何形式的遗传信息。'),B('Its small size means it cannot undergo evolution.','它体积小，因此不可能演化。')],B('Having a genome is different from possessing a complete cellular production system.','拥有基因组，不等于拥有完整的细胞生产系统。'),B('Viruses contain genetic information but rely on host cells for key reproductive processes, including translation. They can evolve, and dependence on a host is not explained by an absence of heredity.','病毒具有遗传信息，但关键繁殖过程依赖宿主细胞，包括翻译。它们能够演化，宿主依赖并不是因为没有遗传性。'));
C('B07.03',B('A community contains only taxa A and B. Taxon A remains at 100 cells while taxon B rises from 100 to 900. What happens to A’s relative abundance, and what can be inferred about its absolute count?','某群落只含 A、B 两个类群。A 保持 100 个细胞，B 从 100 增至 900。A 的相对丰度怎样变化？能推断其绝对数量怎样？'),[
 B('Its relative abundance falls from 50% to 10%, although its absolute count is unchanged.','相对丰度从 50% 降至 10%，但绝对数量不变。'),B('Its relative abundance falls, proving that 80% of A cells died.','相对丰度下降，证明 A 的 80% 细胞死亡。'),B('Its relative abundance stays 50% because its own count is unchanged.','自身数量不变，所以相对丰度仍为 50%。')],B('A proportion depends on both the numerator and the total denominator.','比例既取决于分子，也取决于总量分母。'),B('Initially A/(A+B)=100/200=0.5; later it is 100/1000=0.1. Relative data can change because other taxa change, so they do not alone determine absolute abundance.','最初 A/(A+B)=100/200=0.5，后来为 100/1000=0.1。其他类群变化也能改变相对数据，因此仅相对丰度不能确定绝对数量变化。'),'v3');
C('B07.04',B('A phagocyte responds rapidly to a common molecular pattern shared by several microbes. Which feature best identifies this as innate recognition?','吞噬细胞迅速响应多种微生物共有的分子模式。哪项最符合固有免疫识别的特征？'),[
 B('Pattern-recognition mechanisms detect shared features without requiring prior exposure to each exact microbe.','模式识别机制检测共有特征，不要求先前接触每一种具体微生物。'),B('Each response requires production of a unique antibody after that exact infection.','每次响应都必须在该次感染后产生一种独有抗体。'),B('Innate responses cannot involve receptors or cellular signaling.','固有免疫响应不可能涉及受体或细胞信号。')],B('Compare broad pattern recognition with clonally specific adaptive recognition.','比较广泛模式识别与克隆特异的适应性识别。'),B('Innate receptors can recognize conserved microbial patterns and trigger rapid responses. This differs from the antigen-specific clonal expansion characteristic of adaptive immunity, although the two systems interact.','固有免疫受体可识别保守微生物模式并触发快速响应。这不同于适应性免疫典型的抗原特异克隆扩增，但两系统相互作用。'));
C('B07.05',B('After an initial antigen exposure, a later exposure produces a faster, stronger antigen-specific response in this experiment. Which mechanism best explains it?','实验中，初次抗原接触后，再次接触引起更快、更强的抗原特异响应。哪种机制最能解释？'),[
 B('Memory lymphocytes generated during the earlier response contribute to the later response.','先前响应形成的记忆淋巴细胞参与了后续响应。'),B('Every body cell independently becomes an antibody-producing cell.','每个体细胞都独立变为抗体生产细胞。'),B('The antigen deliberately teaches individual antibodies how to change their goals.','抗原有意识地教导单个抗体改变目标。')],B('Focus on selection, expansion and persistence of antigen-specific cell populations.','关注抗原特异细胞群的选择、扩增与持续存在。'),B('Adaptive responses can leave memory B and T cell populations that respond more effectively on re-exposure. The mechanism concerns cellular populations and molecular recognition, not intention or conversion of all body cells.','适应性响应可留下记忆 B、T 细胞群，在再次接触时更有效地响应。机制涉及细胞群与分子识别，不涉及意图，也不使所有体细胞转变。'));
C('B07.06',B('A test has high sensitivity, but the tested condition is rare and specificity is imperfect. What additional information is needed to interpret a positive result at population level?','某检测灵敏度高，但待检状态很罕见且特异度并非完美。解释人群中的阳性结果还需要什么信息？'),[
 B('Prevalence and specificity, because false positives can form a substantial share of positive results.','患有该状态的比例与特异度，因为假阳性可能占阳性结果的相当部分。'),B('Sensitivity alone, which always equals the probability that a positive result is true.','仅灵敏度，因为它总等于阳性结果为真的概率。'),B('Only the number of negative tests; prior frequency is irrelevant.','只需阴性检测数量，先验频率无关。')],B('P(positive | condition) and P(condition | positive) reverse the conditioning.','P(阳性｜有该状态) 与 P(有该状态｜阳性) 的条件方向相反。'),B('Sensitivity describes positives among those with the condition. Positive predictive value also depends on how common the condition is and the false-positive rate among those without it. These conditional probabilities are not interchangeable.','灵敏度描述有该状态者中的阳性比例。阳性预测值还依赖状态常见程度及无该状态者中的假阳性率，两种条件概率不能互换。'));

C('B08.01',B('Two embryonic cells have the same DNA sequence but develop different fates in different locations. What is a plausible explanation?','两个胚胎细胞 DNA 序列相同，却在不同位置形成不同命运。哪项是合理解释？'),[
 B('Different signals and regulatory states lead to different patterns of gene expression.','不同信号与调控状态导致不同基因表达图样。'),B('Identical DNA forces every cell to express every gene at the same level.','DNA 相同就迫使每个细胞以相同水平表达全部基因。'),B('A cell must discard its entire genome before differentiating.','细胞分化前必须丢弃整个基因组。')],B('The genome provides possibilities; regulation helps determine which are expressed.','基因组提供可能性，调控帮助决定哪些可能性被表达。'),B('Cell fate depends on gene-regulatory networks, signals, history and interactions. Different expression states can arise with the same genome; differentiation does not generally require loss of the whole genome.','细胞命运取决于基因调控网络、信号、历史与相互作用。相同基因组可形成不同表达状态，分化通常不要求失去整个基因组。'));
C('B08.02',B('A developmental gene activates only where signal concentration exceeds a threshold and a required receptor is present. A cell has high signal but no functional receptor. What does this model predict?','某发育基因仅在信号浓度超过阈值且存在所需受体时激活。一个细胞信号很高，但没有功能性受体。模型预测什么？'),[
 B('High signal alone is insufficient to activate the gene through this pathway.','仅高信号不足以通过该通路激活基因。'),B('The gene must activate because the concentration threshold is exceeded.','超过浓度阈值，所以基因必定激活。'),B('The missing receptor necessarily changes the signal molecule into DNA.','缺失受体必然使信号分子变成 DNA。')],B('The rule contains two required conditions joined by “and.”','这条规则包含由“且”连接的两个必要条件。'),B('Both concentration and receptor competence are required in the stated model. A signal can be present without being transduced; threshold reasoning must include all conditions, not just the measured concentration.','给定模型同时要求浓度达标与受体功能。信号存在不代表能被传递，阈值推理必须包括所有条件，而非仅测得浓度。'));
C('B08.03',B('A neuron receives a stronger stimulus above threshold. In the usual action-potential model, which change commonly carries stimulus intensity along its axon?','神经元接受更强的阈上刺激。在通常动作电位模型中，哪种变化常沿轴突编码刺激强度？'),[
 B('A change in firing frequency or timing, while individual action potentials remain approximately all-or-none.','放电频率或时序改变，而单个动作电位仍近似全或无。'),B('Every action potential becomes indefinitely taller in direct proportion to stimulus strength.','每个动作电位随刺激增强无限成比例变高。'),B('All ion gradients disappear permanently after the first spike.','第一次放电后所有离子梯度永久消失。')],B('Distinguish spike amplitude from the pattern of spikes.','区分单次放电幅度与放电序列图样。'),B('Action potentials are regenerative events with a characteristic amplitude under given conditions. Intensity is often represented through spike rate, timing and recruitment, rather than an unlimited increase in each spike’s height.','给定条件下，动作电位是具有特征幅度的再生性事件。强度常由放电频率、时序和神经元募集表示，而不是单次峰值无限增加。'));
C('B08.04',B('An excitatory and an inhibitory synaptic input arrive close together at a neuron. Why can the outcome differ from applying the excitatory input alone?','兴奋性与抑制性突触输入几乎同时到达神经元。为何结果可能不同于仅有兴奋性输入？'),[
 B('Inputs interact through membrane voltage and conductance, affecting whether threshold is reached.','输入通过膜电位与电导相互影响，改变是否达到阈值。'),B('Inhibitory inputs always destroy the neuron’s DNA instantly.','抑制性输入总会立即破坏神经元 DNA。'),B('Each synapse creates a completely separate axon with no shared membrane.','每个突触都产生独立轴突，彼此没有共同膜。')],B('The neuron integrates inputs; their location, timing and reversal potentials matter.','神经元整合输入；位置、时序与反转电位都重要。'),B('Excitatory and inhibitory conductances can alter depolarization and shunt other inputs. A simple signed-sum model is useful, but real integration also depends on timing, location and membrane properties.','兴奋性与抑制性电导可改变去极化，也可分流其他输入。带符号相加是有用简化，但真实整合还依赖时序、位置与膜性质。'));
C('B08.05',B('A sensory receptor responds strongly when a constant stimulus begins, then its response decreases while the stimulus continues. What is this pattern consistent with?','感觉受体在恒定刺激开始时响应强烈，刺激持续期间响应逐渐减弱。这与什么现象一致？'),[
 B('Sensory adaptation that changes responsiveness during sustained stimulation.','持续刺激期间响应性改变的感觉适应。'),B('Proof that the stimulus vanished, regardless of independent measurements.','无论独立测量如何，都证明刺激消失。'),B('Proof that all sensory neurons encode only stimulus duration and never change.','证明所有感觉神经元只编码刺激持续时间且永不改变。')],B('A changing neural response need not mean the external stimulus changed.','神经响应变化不一定意味着外界刺激变化。'),B('Adaptation can reduce response to a sustained input and emphasize changes. Its degree and mechanism vary by receptor and circuit; the observed response should be distinguished from the physical stimulus.','适应可降低对持续输入的响应并突出变化，其程度与机制因受体和回路而异。应区分观察到的响应与物理刺激本身。'));
C('B08.06',B('A result is reproducible in a cultured cell line. What is the most defensible next interpretation for a whole organism?','某结果在培养细胞系中可以重复。对整个生物体最稳妥的下一步解释是什么？'),[
 B('It supports a mechanism in that model, while organism-level relevance needs additional evidence.','它支持该模型中的机制，整体生物层面的适用性仍需额外证据。'),B('It proves identical effects in every tissue and every species.','它证明所有组织、所有物种都有相同效应。'),B('It is automatically meaningless because only whole-organism work can yield knowledge.','它自动毫无意义，因为只有整体生物实验能产生知识。')],B('A model can be informative without reproducing every feature of the target system.','模型可以有信息价值，而不必重现目标系统的每个特征。'),B('Cell models isolate mechanisms but omit many interactions, such as tissue context and systemic regulation. Use their evidence within scope, then test transfer with suitable additional models and ethically justified designs.','细胞模型有助于分离机制，但遗漏组织情境和全身调控等相互作用。应在范围内使用证据，再通过适当模型与合乎伦理的设计检验可推广性。'));

C('B09.01',B('A microscope image is digitally enlarged twofold after capture. What changes if no new optical information is acquired?','显微图像拍摄后经数字放大两倍，未获得新的光学信息。什么会改变？'),[
 B('Displayed size increases, but optical resolving power does not improve.','显示尺寸增大，但光学分辨能力不提高。'),B('Two previously unresolved structures necessarily become truly resolved.','原本不能分辨的两个结构必然获得真实分辨。'),B('The actual specimen doubles in physical length.','真实样本的物理长度加倍。')],B('Magnification describes displayed size; resolution concerns distinguishable detail.','放大描述显示尺寸，分辨率涉及能区分的细节。'),B('Digital enlargement spreads existing pixels over a larger display. It does not recover spatial detail that was never resolved during acquisition; an updated scale bar must remain consistent with the resized image.','数字放大将现有像素显示得更大，不能恢复采集时未分辨出的细节。图像缩放后，比例尺必须同步保持正确。'));
C('B09.02',B('A treatment is assigned independently to six animals. Each animal is measured three times on the same sample. How many independent biological experimental units are present?','处理独立分配给六只动物，每只动物的同一样本测三次。共有多少个独立生物实验单位？'),[
 B('Six.','六个。'),B('Eighteen.','十八个。'),B('One hundred eight.','一百零八个。')],B('Repeated technical measurements do not create new independently assigned animals.','技术重复测量不会创造新的独立分配动物。'),B('The animals are the six biological units. Repeated measurements can estimate measurement variation but are correlated within animal and do not multiply the number of independently assigned units.','六只动物是六个生物单位。重复测量可估计测量变异，但同一动物内部数据相关，不会增加独立分配单位数。'));
C('B09.03',B('Two groups have equal means but one has much greater spread. Which graph would help reveal the difference hidden by the means?','两组均值相同，但一组分散程度大得多。哪种图有助于揭示均值隐藏的差异？'),[
 B('Individual data points or distribution plots with a clear common scale.','在清晰共同尺度上显示个体点或分布图。'),B('Two bars showing only the means, without spread or observations.','只显示均值的两个条形，不含分散或个体观测。'),B('A decorative illustration with no quantitative axis.','没有定量坐标的装饰性插图。')],B('A central value alone does not describe a distribution.','仅中心值不能描述整个分布。'),B('Raw points, box plots or suitable density summaries reveal spread and possible outliers. The plot should also make sample size and units clear; equal means do not establish identical distributions.','原始点、箱线图或适当密度摘要能显示分散程度与可能的异常值，还应明确样本量和单位。均值相等不等于分布相同。'));
C('B09.04',B('Two sequence alignments both report 90% identity. One covers 20 bases and the other 2000 bases of a long gene. Why is the percentage alone insufficient?','两个序列比对都报告 90% 一致性，一个覆盖长基因的 20 个碱基，另一个覆盖 2000 个。为何只看百分比不足？'),[
 B('Alignment length, coverage, gaps and chance similarity affect interpretation.','比对长度、覆盖度、缺口与随机相似性都会影响解释。'),B('Percent identity uniquely proves identical function regardless of coverage.','无论覆盖度如何，一致性百分比都能唯一证明功能相同。'),B('Long and short matches must have identical statistical support.','长匹配与短匹配必定具有相同统计支持。')],B('The same fraction can summarize very different amounts of evidence.','相同分数可以概括截然不同的证据量。'),B('A short matching segment can arise by chance or represent only one shared domain. Interpretation needs coverage and alignment context, and even strong sequence similarity does not by itself prove identical biological function.','短匹配片段可能偶然出现，也可能只代表一个共享结构域。解释需要覆盖度与比对情境，即使高度相似也不能单独证明生物功能相同。'));
C('B09.05',B('A study tests thousands of genes and reports every raw p-value below 0.05 as a discovery. What issue must be addressed?','研究检验数千个基因，并把每个原始 p 值低于 0.05 的结果都称为发现。必须处理什么问题？'),[
 B('Multiple testing can produce many false positives, so an appropriate error-control strategy is needed.','多重检验可能产生许多假阳性，需要适当的错误控制策略。'),B('A p-value below 0.05 proves a causal mechanism for that gene.','p 值低于 0.05 就证明该基因的因果机制。'),B('Testing more genes automatically makes every individual result certain.','检验更多基因会自动让每项结果确定无疑。')],B('Repeated opportunities for false positives accumulate across a large test family.','大量检验会累积出现假阳性的机会。'),B('Even under true null hypotheses, some small p-values occur by chance. Family-wise or false-discovery-rate control can address different goals; effect size, design and independent validation remain relevant.','即使零假设为真，也会随机出现小 p 值。整体错误率或错误发现率控制服务不同目标；效应大小、研究设计与独立验证仍然重要。'));
C('B09.06',B('An analyst notices that excluding two inconvenient observations changes a result from nonsignificant to significant. The exclusions were not planned. What should the report do?','分析者发现排除两个不方便的观测后，结果由不显著变为显著，但排除并非预先计划。报告应怎样处理？'),[
 B('Disclose the exclusions and reasons, show sensitivity to them and avoid presenting the choice as prespecified.','披露排除及理由，展示结果对此的敏感性，并避免声称是预先指定。'),B('Hide the original analysis because only the significant version is informative.','隐藏原分析，因为只有显著版本有信息。'),B('Claim that significance proves the excluded observations were wrong.','宣称显著性证明被排除观测错误。')],B('Separate a justified quality rule from selecting data to obtain a desired conclusion.','区分有理由的质量规则与为得到期望结论而选择数据。'),B('Transparent reporting lets readers assess the influence of discretionary choices. A changed p-value does not validate an exclusion; quality criteria, full results and sensitivity analyses provide the relevant evidence.','透明报告让读者评估自主选择的影响。p 值改变不能证明排除合理；质量标准、完整结果与敏感性分析才提供相关证据。'));

C('B10.01',B('Blocking protein X reduces pathway output. Restoring X restores output. Which conclusion is best supported, assuming suitable controls?','阻断蛋白 X 降低通路输出，恢复 X 又恢复输出。假定对照适当，最支持哪项结论？'),[
 B('X contributes causally to the output in this tested system, though its precise molecular role needs more evidence.','X 在所测系统中对输出有因果贡献，但精确分子作用仍需更多证据。'),B('X is necessarily the only protein involved in the entire pathway.','X 必定是整条通路唯一涉及的蛋白质。'),B('The rescue proves X physically binds every downstream molecule.','挽救实验证明 X 与所有下游分子直接结合。')],B('Perturbation plus rescue strengthens causal inference but does not specify every interaction.','扰动加挽救增强因果推断，但不能确定每一次相互作用。'),B('Loss and rescue provide stronger evidence than correlation alone. They support a role for X under the tested conditions, while direct binding, exclusivity and the detailed mechanism require additional experiments.','失活与挽救比单独相关更有力，支持 X 在给定条件下的作用，但直接结合、唯一性和细节机制仍需额外实验。'));
C('B10.02',B('An allele rises in frequency after a population bottleneck, with no measured advantage. Which explanation must remain possible?','种群瓶颈后，某等位基因频率升高，但没有测得其优势。哪种解释仍必须保留？'),[
 B('Genetic drift from random sampling, alongside other hypotheses that need testing.','随机抽样造成的遗传漂变，以及其他仍需检验的假说。'),B('Positive natural selection is proven by every frequency increase.','只要频率升高就证明存在正向自然选择。'),B('The allele must have arisen because organisms consciously needed it.','该等位基因必定因生物有意识地需要而产生。')],B('A frequency change does not by itself identify the evolutionary mechanism.','频率改变本身不能唯一确定演化机制。'),B('Bottlenecks can amplify sampling effects and change allele frequencies through drift. Selection may also occur, but a frequency increase without further evidence does not distinguish these mechanisms.','瓶颈可放大抽样效应，使漂变改变等位基因频率。选择也可能存在，但没有更多证据的频率升高不能区分这些机制。'));
C('B10.03',B('An animal’s oxygen consumption rises while its blood oxygen concentration stays nearly constant. Which interpretation is possible?','动物耗氧量上升，但血氧浓度几乎不变。哪种解释可能成立？'),[
 B('Delivery and uptake fluxes changed while feedback kept the measured concentration near its previous value.','输送与摄取通量发生变化，反馈使所测浓度保持接近原值。'),B('A constant concentration proves that no oxygen enters or leaves the blood.','浓度恒定证明没有氧进入或离开血液。'),B('Concentration and total transport per unit time are always the same quantity.','浓度与单位时间总输送量始终是同一物理量。')],B('A pool’s concentration and the rates of flow through it can change independently.','一个库的浓度与通过它的流量可以相互独立变化。'),B('Stable concentration can coexist with high turnover when input and output balance. Interpreting physiology requires rates, volumes and regulatory context as well as a single measured concentration.','输入输出平衡时，稳定浓度可以与高周转共存。生理解释还需要速率、体积及调控情境，而不只是一个浓度值。'));
C('B10.04',B('A predator and its prey show repeated population cycles with predator peaks following prey peaks. What can this time series establish by itself?','捕食者与猎物数量反复周期变化，捕食者峰值晚于猎物峰值。仅凭该时间序列能说明什么？'),[
 B('A lagged association compatible with interaction, but not unique proof of one causal model.','存在与相互作用相容的滞后关联，但不能唯一证明某个因果模型。'),B('Predation is proven to be the only factor affecting both populations.','证明捕食是影响两种群的唯一因素。'),B('The earlier peak must be caused by the later peak in every cycle.','每个周期中，较早峰值必定由较晚峰值造成。')],B('Shared environmental drivers can also create correlated, lagged patterns.','共同环境驱动也可能产生相关且有滞后的图样。'),B('The pattern is useful evidence for model building, but resources, climate and other species may contribute. Additional observations or controlled perturbations help distinguish candidate mechanisms.','该图样有助于建立模型，但资源、气候和其他物种也可能参与。更多观测或控制扰动有助于区分候选机制。'));
C('B10.05',B('A microscope scale bar labeled 20 μm spans 80 pixels. A structure spans 200 pixels in the same image. What is its estimated length?','显微图上标注 20 μm 的比例尺长 80 像素，同图结构长 200 像素。估计实际长度是多少？'),[
 B('50 μm.','50 μm。'),B('8 μm.','8 μm。'),B('4000 μm.','4000 μm。')],B('Convert pixels using micrometres per pixel from the scale bar.','先由比例尺求每像素对应的微米数。'),B('The scale is 20/80=0.25 μm per pixel. Thus 200 pixels correspond to 200×0.25=50 μm, assuming the image has not been distorted and both measurements use the same scale.','尺度为 20/80=0.25 μm/像素，故 200 像素对应 50 μm，前提是图像未畸变且两项测量采用同一尺度。'));
C('B10.06',B('In an integrated exam problem, a graph shows a treatment-associated change but the prompt asks for a mechanism and a follow-up experiment. Which response addresses all parts?','综合题的图显示某变化与处理有关，但题目要求机制及后续实验。哪种作答覆盖了全部要求？'),[
 B('Describe the evidence, propose a conditional mechanism and give a controlled test that could distinguish it from an alternative.','描述证据，提出有条件的机制，并设计能区分该机制与替代解释的对照检验。'),B('Restate the graph trend and label it a proven mechanism without another test.','复述图中趋势，直接称为已证明机制，不再检验。'),B('List unrelated facts while ignoring the graph’s axes and experimental controls.','列举无关事实，忽略坐标轴与实验对照。')],B('Separate observation, explanation and a discriminating prediction.','分开观察、解释与能够区分假说的预测。'),B('A complete synthesis connects the measured pattern to a plausible model, states its limits and proposes a test with interpretable controls. A mechanism remains an inference until evidence distinguishes it from competing explanations.','完整综合应把测得图样与合理模型相连，说明局限，并提出带可解释对照的检验。在证据区分竞争解释之前，机制仍是推断。'));

export function enrichBiologyChecks(lesson){
  const check=checks.get(lesson.id);
  return check?{...lesson,exercises:[...lesson.exercises,check]}:lesson;
}
